import {appendWayglassBag} from './wayglass-ui.js';
import {PHYSICAL_LORE} from './physical-lore-content.js';
import {physicalState,carryPhysical,dropPhysical} from './physical-lore.js?v=5.16.0';
import {artifactGlyph} from './physical-lore-art.js';
const make=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
export function physicalSatchel(world,onChange,onBack){const root=make('section');root.className='key-satchel';
 const paint=()=>{root.replaceChildren();const p=physicalState(world.state);root.append(make('h3','Objects with a purpose'),make('p','Carry a piece to its matching silhouette. It stays with you across roads and saves. Turning, pumping, growing and leaving a silence change what the mechanism does.'));
 if(p.held){const held=PHYSICAL_LORE.find(e=>e.id===p.held),bar=make('div');bar.className='key-actions';bar.append(make('strong','In hand: '+held.name));for(const [text,fn]of [['Pack safely',()=>{p.held=null;}],['Set on this floor',()=>{dropPhysical(world);}]]){const b=make('button',text);b.onclick=()=>{fn();onChange();paint();};bar.append(b);}root.append(bar);}
 appendWayglassBag(root,world.state,{onOpen:()=>world.callbacks.onOpenWayglass?.(),onGrid:()=>world.callbacks.onWayglassGrid?.()});const entries=PHYSICAL_LORE.filter(e=>p.taken.includes(e.id));if(!entries.length)root.append(make('p','Look for small copper, clay and cloth objects beside workshop walls and side-room benches. The first appears after the clay bench in Rook’s workshop.'));
 for(const e of entries){const card=make('article'),art=make('canvas');art.width=112;art.height=112;art.setAttribute('aria-label',e.name);const c=art.getContext('2d');c.translate(56,56);artifactGlyph(c,e.glyph,1.8,e.color);card.append(art,make('h4',e.name),make('p',e.meaning+(['brake-lantern','star-lens'].includes(e.id)?' While carried, its light exposes nearby hiding places.':'')));const status=p.completed.includes(e.id)?'Working in the world':p.installed.includes(e.id)?'Fitted · return to adjust':p.dropped[e.id]?'Set down · retrieve or recall':p.held===e.id?'Carried':'Packed';card.append(make('small',status+' · '+e.device));if(p.bag.includes(e.id)){const b=make('button',p.held===e.id?'In hand':'Carry');b.disabled=p.held===e.id;b.onclick=()=>{carryPhysical(world,e.id);onChange();paint();};card.append(b);}if(p.dropped[e.id]){const b=make('button','Recall to satchel');b.onclick=()=>{delete p.dropped[e.id];if(!p.bag.includes(e.id))p.bag.push(e.id);p.held=e.id;onChange();paint();};card.append(b);}if(p.installed.includes(e.id)&&!p.completed.includes(e.id)){const b=make('button','Retrieve fitted piece');b.onclick=()=>{p.installed=p.installed.filter(id=>id!==e.id);p.bag.push(e.id);p.held=e.id;delete p.steps[e.id];delete p.clocks[e.id];onChange();paint();};card.append(b);}root.append(card);}
 const back=make('button','Back to pause');back.onclick=onBack;root.append(back);};paint();return root;}
let lastBadge='';export function physicalBadge(world,visible){const p=physicalState(world.state),e=PHYSICAL_LORE.find(e=>e.id===p.held);let badge=document.querySelector('#carried-key');if(!badge){badge=make('aside');badge.id='carried-key';badge.setAttribute('aria-label','Carried key item');document.querySelector('#game').append(badge);}badge.hidden=!visible||!e;if(e&&lastBadge!==e.id){lastBadge=e.id;badge.replaceChildren();const strong=make('strong',e.name),small=make('small','Carry to '+e.device.toLowerCase());badge.append(strong,small);}}
